#include <bits/stdc++.h>
using namespace std;const int D=15,N=2564;short X[N][D];int order_[N],g[D],part;long long dp[16][17],seen=0,kept=0,hist[7]{};signed char q[D];uint16_t B[6];ofstream fo,fb;
void test(){seen++;int c=0;for(int k=0;k<N;k++){int i=order_[k],d=0;for(int j=0;j<D;j++)if(q[j])d+=q[j]*g[j]*X[i][j];if(d>8){if(c==6){c=7;break;}B[c++]=i;}}if(c<=6){hist[c]++;for(int i=c;i<6;i++)B[i]=65535;fo.write((char*)q,D);fb.write((char*)B,12);kept++;if(c==0){cout<<"POTENTIAL free"<<endl;fo.flush();fb.flush();exit(0);}}if(seen%1000000==0)cout<<"seen "<<seen<<" kept "<<kept<<endl;}
void rec(int j,int n){if(j==D){if(n==0)test();return;}for(int a=-4;a<=4;a++){if(j==0&&(a+4)%2!=part)continue;int w=g[j]*a*a;if(n<w||dp[D-j-1][n-w]==0)continue;q[j]=a;rec(j+1,n-w);}}
int main(int argc,char**argv){part=atoi(argv[1]);string p=to_string(part);fo.open("scan_Q"+p+".bin",ios::binary);fb.open("scan_B"+p+".bin",ios::binary);ifstream f("source.bin",ios::binary);f.read((char*)X,sizeof(X));iota(order_,order_+N,0);mt19937 rng(151519);shuffle(order_,order_+N,rng);for(int i=0;i<D;i++)g[i]=i==14?2:1;dp[0][0]=1;for(int l=1;l<=15;l++)for(int n=0;n<=16;n++)for(int a=-4;a<=4;a++){int w=(l==1?2:1)*a*a;if(n>=w)dp[l][n]+=dp[l-1][n-w];}rec(0,16);cout<<"done seen "<<seen<<" kept "<<kept<<" hist ";for(int i=0;i<=6;i++)cout<<i<<":"<<hist[i]<<" ";cout<<endl;}
